const r = $json;
const processed = r.processed || 0;
const succeeded = r.succeeded || 0;
const failed = r.failed || 0;
const total = r.candidates_total || 0;
const skipped = r.skipped;

if (skipped) {
  return [{ json: { text: `⏸ Paperclip publish skipped: ${skipped}`, succeeded: 0, failed: 0 } }];
}

let text = `📰 Paperclip 발행: ${succeeded}/${processed} 성공 (후보 ${total}건)`;
if (failed > 0) {
  const reasons = (r.items || [])
    .filter(i => !i.success)
    .map(i => i.reason || i.error)
    .filter(Boolean)
    .slice(0, 3);
  text += `\n❌ 실패 ${failed}건: ${reasons.join(', ')}`;
}

return [{ json: { text, succeeded, failed, processed, total } }];
